@using sv_781f1ddd5aca40bc9b36a95a6b080f95.Services

<div class="security-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <span>Change Password</span>
                <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
            </button>

            @if (_passwordExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                    </div>
                    <button class="btn-primary" @onclick="ChangePasswordAsync">Update Password</button>

                    @if (!string.IsNullOrEmpty(_passwordMessage))
                    {
                        <div class="toast-message @(_passwordError ? "error" : "success")">@_passwordMessage</div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
                <label class="toggle-item">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span>Enable Two-Factor Authentication</span>
                </label>
            </div>
            @if (_settings?.LastPasswordChange.HasValue == true)
            {
                <p class="last-change">Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _settings!.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != _settings.Sessions.FirstOrDefault())
                                {
                                    <button class="btn-danger btn-small" @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message @(_messageError ? "error" : "success")">@_message</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;
    private bool _loading = true;
    private bool _passwordExpanded;
    private bool _twoFactorEnabled;

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordMessage = "";
    private bool _passwordError;

    private ActiveSession? _sessionToRevoke;
    private string _message = "";
    private bool _messageError;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettingsAsync();
    }

    private async Task LoadSettingsAsync()
    {
        _loading = true;
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "New password and confirmation do not match.";
            _passwordError = true;
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordError = true;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _message = $"Session on {_sessionToRevoke.Device} revoked.";
            _messageError = false;
            _sessionToRevoke = null;
            await LoadSettingsAsync();
        }
        catch (Exception ex)
        {
            _message = $"Error revoking session: {ex.Message}";
            _messageError = true;
            _sessionToRevoke = null;
        }
    }
}
